import com.midtermwork.*;import com.badlogic.gdx.*;import com.badlogic.gdx.graphics.*;import com.badlogic.gdx.backends.lwjgl3.*;
public class BuildEffectScreenCheck {
 public static void main(String[] args){final String dir=args.length>0?args[0]:"../build/build-effect-check";Lwjgl3ApplicationConfiguration c=new Lwjgl3ApplicationConfiguration();c.setTitle("midtermwork - build effects verification");c.setWindowedMode(1152,648);c.setForegroundFPS(60);c.disableAudio(true);
 new Lwjgl3Application(new Main(){GameWorld w;int scene,frames;java.lang.reflect.Field field(Class<?> type,String name)throws Exception{java.lang.reflect.Field f=type.getDeclaredField(name);f.setAccessible(true);return f;}
 public void create(){super.create();setup();}
 void target(float x,float y){GameWorld.Enemy e=new GameWorld.Enemy(x,y,true);e.primaryType=GameWorld.Element.NORMAL;e.hp=e.maxHp=10000;e.timer=1000;w.enemies.add(e);}
 void setup(){try{w=new GameWorld();w.enemies.clear();w.spikes.clear();w.blocks.clear();w.blocks.add(new GameWorld.Block(0,0,4500,112));w.level=20;w.evolution=1;w.maxHp=w.hp=8;w.setDropSeed(0);w.messageTime=0;int[] ranks=(int[])field(GameWorld.class,"buildRanks").get(w);ranks[scene]=1;GameWorld.Skill[] slots=(GameWorld.Skill[])field(GameWorld.class,"equipped").get(w);java.util.Arrays.fill(slots,null);slots[0]=scene==0?GameWorld.Skill.EMBER:scene==1?GameWorld.Skill.FLAME_CHARGE:GameWorld.Skill.DRAGON;java.lang.reflect.Method reset=GameWorld.class.getDeclaredMethod("resetDashCharges");reset.setAccessible(true);reset.invoke(w);field(Main.class,"world").set(this,w);if(scene==0){target(250,112);target(275,180);}if(scene==2){target(250,112);target(450,112);}w.trySkill(0);frames=0;}catch(Exception ex){throw new RuntimeException(ex);}}
 public void render(){super.render();if(++frames==(scene==0?28:scene==1?24:27)){if(scene==0&&w.buildEffects.isEmpty())throw new AssertionError("fire burst");if(scene==1&&w.buildEffects.isEmpty())throw new AssertionError("dash trail");if(scene==2&&w.skillShots.stream().noneMatch(s->s.secondary))throw new AssertionError("dragon fork");Pixmap p=Pixmap.createFromFrameBuffer(0,0,Gdx.graphics.getBackBufferWidth(),Gdx.graphics.getBackBufferHeight());java.io.File f=new java.io.File(dir,"build-"+scene+".png");f.getParentFile().mkdirs();PixmapIO.writePNG(Gdx.files.absolute(f.getAbsolutePath()),p,-1,true);p.dispose();if(++scene==3){System.out.println("PASS: fire explosion, two-charge dash trail and dragon fork rendered from actual casts");Gdx.app.exit();}else setup();}}
 },c);}
}
